import json

class DeviceShadowManager:
    """
    AWS IoT Core Device Shadow simulator.
    Maintains desired vs reported state and generates delta documents.
    Topic convention: $aws/things/{thingName}/shadow/update
    """
    def __init__(self, thing_name: str):
        self.thing_name = thing_name
        self.state = {
            "desired": {},
            "reported": {}
        }
        self.version = 0

    def update_desired(self, desired_patch: dict):
        self.state["desired"].update(desired_patch)
        self.version += 1
        return self.compute_delta()

    def update_reported(self, reported_patch: dict):
        self.state["reported"].update(reported_patch)
        self.version += 1
        return self.compute_delta()

    def compute_delta(self):
        delta = {}
        for k, v in self.state["desired"].items():
            if self.state["reported"].get(k) != v:
                delta[k] = v
        return delta

shadow = DeviceShadowManager("SMART_HVAC_PUMP_04")
# 1. Device reports initial operational state
shadow.update_reported({"pump_speed_rpm": 1200, "valve_open": False, "mode": "ECO"})
# 2. Cloud updates desired target state
delta1 = shadow.update_desired({"pump_speed_rpm": 1800, "valve_open": True})

print(f"Thing Name: {shadow.thing_name} | Version: {shadow.version}")
print(f"Reported State: {shadow.state['reported']}")
print(f"Desired State: {shadow.state['desired']}")
print(f"Generated Delta for Field Actuator: {delta1}")

